use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let value = input.as_object().unwrap();
    let size = value.get("size").unwrap().as_i64().unwrap();
    let values = value.get("values").unwrap().as_array().unwrap();
    let mut result = Vec::new();
    let mut current_chunk = Vec::new();
    for &value in values {
        current_chunk.push(value.as_i64().unwrap());
        if current_chunk.len() == size {
            result.push(serde_json::Value::Array(current_chunk));
            current_chunk.clear();
        }
    }
    if !current_chunk.is_empty() {
        result.push(serde_json::Value::Array(current_chunk));
    }
    Value::Array(result)
}
